// Start / finish gantry
const gateF=frame(0),gate=new THREE.Group();gate.position.copy(gateF.p);gate.position.y+=4;gate.rotation.y=Math.atan2(gateF.tangent.x,gateF.tangent.z);const postmat=mat(0x282e29,.5,.3);for(const x of [-8,8]){let post=new THREE.Mesh(new THREE.BoxGeometry(.4,8,.45),postmat);post.position.set(x,0,0);post.castShadow=true;gate.add(post)}let beam=new THREE.Mesh(new THREE.BoxGeometry(16,.7,.6),lime);beam.position.y=3.6;gate.add(beam);let banner=new THREE.Mesh(new THREE.BoxGeometry(10,1.3,.5),dark);banner.position.set(0,2.4,0);gate.add(banner);scene.add(gate);
let checkerMat=mat(0xf4eedb);for(let i=0;i<16;i++){let b=new THREE.Mesh(new THREE.BoxGeometry(.8,.08,.8),i%2?dark:checkerMat);b.position.copy(gateF.p).addScaledVector(gateF.side,-6.4+i*.85);b.position.y+=.23;scene.add(b)}
function makeBike(color){let root=new THREE.Group(),tilt=new THREE.Group();root.add(tilt);const body=new THREE.Mesh(new THREE.BoxGeometry(1.05,.42,1.5),color);body.position.set(0,.83,-.02);body.castShadow=true;tilt.add(body);let nose=new THREE.Mesh(new THREE.BoxGeometry(.88,.25,.68),color);nose.position.set(0,1.02,.92);nose.rotation.x=-.16;tilt.add(nose);let seat=new THREE.Mesh(new THREE.BoxGeometry(.68,.2,.9),dark);seat.position.set(0,1.1,-.38);tilt.add(seat);
// front and rear rack bars
for(const z of [-1,.98]){let bar=new THREE.Mesh(new THREE.BoxGeometry(1.12,.1,.38),metal);bar.position.set(0,.8,z);tilt.add(bar)}
// rider legs and torso
const riderMat=mat(0x252c29,.8),helmet=mat(0xe4e4d7,.35,.08);let torso=new THREE.Mesh(new THREE.BoxGeometry(.55,.7,.38),riderMat);torso.position.set(0,1.62,-.13);torso.rotation.x=-.14;tilt.add(torso);let head=new THREE.Mesh(new THREE.SphereGeometry(.27,16,12),helmet);head.position.set(0,2.12,.04);tilt.add(head);let visor=new THREE.Mesh(new THREE.BoxGeometry(.39,.12,.08),dark);visor.position.set(0,2.13,.27);tilt.add(visor);for(let s of [-1,1]){let leg=new THREE.Mesh(new THREE.BoxGeometry(.23,.64,.26),color);leg.position.set(s*.33,1.18,-.34);leg.rotation.x=-.28;tilt.add(leg);let arm=new THREE.Mesh(new THREE.CylinderGeometry(.1,.13,.68,8),riderMat);arm.position.set(s*.36,1.67,.43);arm.rotation.x=-.72;arm.rotation.z=s*.2;tilt.add(arm);let handle=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,.92,8),metal);handle.rotation.z=Math.PI/2;handle.position.set(0,1.45,.75);tilt.add(handle)}
let wheels=[];for(let z of [-.9,.92])for(let x of [-.76,.76]){let tire=new THREE.Mesh(new THREE.TorusGeometry(.36,.14,10,20),rubber);tire.rotation.y=Math.PI/2;tire.position.set(x,.47,z);tire.castShadow=true;tilt.add(tire);let hub=new THREE.Mesh(new THREE.CylinderGeometry(.16,.16,.12,12),metal);hub.rotation.z=Math.PI/2;hub.position.copy(tire.position);tilt.add(hub);wheels.push(tire);let support=new THREE.Mesh(new THREE.CylinderGeometry(.055,.055,.55,8),metal);support.position.set(x*.75,.7,z);support.rotation.z=x>0?-.3:.3;tilt.add(support)}
// headlamp
let lamp=new THREE.Mesh(new THREE.BoxGeometry(.35,.15,.06),mat(0xffe6a3,.25,.2));lamp.position.set(0,1.1,1.28);tilt.add(lamp);root.userData={tilt,wheels};scene.add(root);return root}
let bikes=[makeBike(lime),makeBike(red),makeBike(blue),makeBike(gold)];
const trackLength=(()=>{let len=0;for(let i=0;i<N;i++)len+=points[i].distanceTo(points[(i+1)%N]);return len})();
const racers=[{bike:bikes[0],player:true,progress:0,offset:0,speed:0,color:lime},{bike:bikes[1],progress:-.014,offset:-2.1,speed:19,color:red},{bike:bikes[2],progress:-.032,offset:2.1,speed:18,color:blue},{bike:bikes[3],progress:-.048,offset:-3.8,speed:17,color:gold}];
let keys={left:false,right:false,go:false,brake:false,boost:false},state='ready',elapsed=0,count=3,lapNow=1,toastTimer=0,lastLap=0,boost=100,shake=0;
const speedEl=document.querySelector('#speed'),posEl=document.querySelector('#position'),lapEl=document.querySelector('#lap'),timerEl=document.querySelector('#timer'),countEl=document.querySelector('#countdown'),hintEl=document.querySelector('#racehint'),overlay=document.querySelector('#overlay'),titleEl=document.querySelector('#menutitle'),textEl=document.querySelector('#menutext'),startBtn=document.querySelector('#startbtn'),mapdot=document.querySelector('#mapdot');
function startRace(){state='countdown';count=3;elapsed=0;lapNow=1;boost=100;racers.forEach((r,i)=>{r.progress=-i*.014;r.offset=i===0?0:(i%2? -2:2);r.speed=0});overlay.classList.add('hidden');hintEl.textContent='3 LAPS · 4 RIDERS';startBtn.blur()}
startBtn.addEventListener('click',startRace);window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(k==='w'||k==='arrowup')keys.go=true;if(k==='s'||k==='arrowdown')keys.brake=true;if(k==='a'||k==='arrowleft')keys.left=true;if(k==='d'||k==='arrowright')keys.right=true;if(k===' ')keys.boost=true;if(k==='p'){if(state==='racing')state='paused';else if(state==='paused')state='racing';if(state==='paused'){titleEl.innerHTML='RACE<br><em>PAUSED.</em>';textEl.innerHTML='Take a breath. The desert will still be here.';startBtn.textContent='RESUME RACE&nbsp; ↗';overlay.classList.remove('hidden')}else if(state==='racing')overlay.classList.add('hidden')}if(k==='enter'&&state==='ready')startRace()});window.addEventListener('keyup',e=>{let k=e.key.toLowerCase();if(k==='w'||k==='arrowup')keys.go=false;if(k==='s'||k==='arrowdown')keys.brake=false;if(k==='a'||k==='arrowleft')keys.left=false;if(k==='d'||k==='arrowright')keys.right=false;if(k===' ')keys.boost=false});document.querySelectorAll('.touch button').forEach(b=>{let k=b.dataset.key;const on=e=>{e.preventDefault();keys[k]=true},off=e=>{e.preventDefault();keys[k]=false};b.addEventListener('pointerdown',on);b.addEventListener('pointerup',off);b.addEventListener('pointercancel',off);b.addEventListener('pointerleave',off)});
function place(r,dt){let t=((r.progress%1)+1)%1,f=frame(t);r.bike.position.copy(f.p).addScaledVector(f.side,r.offset);r.bike.position.y+=.08+Math.sin(elapsed*12+r.offset)*Math.min(r.speed*.001,.07);let yaw=Math.atan2(f.tangent.x,f.tangent.z);r.bike.rotation.y=yaw;r.bike.userData.tilt.rotation.z=r.player?THREE.MathUtils.damp(r.bike.userData.tilt.rotation.z,(keys.left?.22:keys.right?-.22:0),7,dt):Math.sin(elapsed*1.6+r.offset)*.035;r.bike.userData.wheels.forEach(w=>w.rotation.x-=r.speed*dt*1.8)}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');toastTimer=1.5}
function fmtTime(sec){let m=Math.floor(sec/60),s=(sec%60).toFixed(2).padStart(5,'0');return `${String(m).padStart(2,'0')}:${s}`}
function finishRace(){state='finished';titleEl.innerHTML='RACE<br><em>COMPLETE.</em>';textEl.innerHTML=`You crossed the line in <b class="resulttime">${posEl.innerText.replace(/\s/g,'')}</b> place with a time of <b class="resulttime">${fmtTime(elapsed)}</b>. Take another shot at the podium.`;startBtn.textContent='RACE AGAIN&nbsp; ↗';overlay.classList.remove('hidden');hintEl.textContent='FINISH / CHECKERED FLAG'}
function update(dt){if(state==='countdown'){count-=dt;if(count>0)countEl.textContent=Math.ceil(count);else{state='racing';countEl.textContent='GO!';toast('GO!');setTimeout(()=>{if(state==='racing')countEl.textContent=''},700)}}else if(state==='racing'){elapsed+=dt;let p=racers[0];let accel=keys.go?17:5;if(keys.brake)accel=-22;let boosting=keys.boost&&boost>0&&p.speed>5;if(boosting){accel+=24;boost=Math.max(0,boost-30*dt)}else boost=Math.min(100,boost+10*dt);let offroad=Math.abs(p.offset)>5.9;p.speed=THREE.MathUtils.clamp(p.speed+accel*dt-(offroad?13:0),0,boosting?37:30);let steer=(keys.right?1:0)-(keys.left?1:0);p.offset+=steer*dt*(2.5+p.speed*.18);p.offset*=Math.pow(.985,dt*60);p.offset=THREE.MathUtils.clamp(p.offset,-9,9);if(offroad&&Math.random()<dt*1.2)toast('OFF TRACK!');p.progress+=p.speed*dt/trackLength;let lap=Math.floor(p.progress)+1;if(lap>lapNow){lapNow=lap;if(lapNow>3){finishRace()}else toast(`LAP ${lapNow}!`)}
for(let i=1;i<racers.length;i++){let r=racers[i];let targetSpeed=20+Math.sin(elapsed*.42+i*2)*2.8;r.speed=THREE.MathUtils.damp(r.speed,targetSpeed,.7,dt);r.progress+=r.speed*dt/trackLength;let curve=frame(((r.progress%1)+1)%1);r.offset=THREE.MathUtils.damp(r.offset,Math.sin(elapsed*.65+i*2)*1.8+(i%2? -1.6:1.6),.55,dt)}
let sorted=[...racers].sort((a,b)=>b.progress-a.progress),rank=sorted.indexOf(p)+1;posEl.innerHTML=`${rank}<small>${rank===1?'ST':rank===2?'ND':rank===3?'RD':'TH'}</small>`;lapEl.textContent=`LAP ${String(Math.min(lapNow,3)).padStart(2,'0')} / 03`;timerEl.textContent=fmtTime(elapsed);if(boosting)hintEl.textContent=`N₂O BOOST · ${Math.round(boost)}%`;else hintEl.textContent='3 LAPS · 4 RIDERS';speedEl.textContent=String(Math.round(p.speed*3.6)).padStart(3,'0');let mapT=((p.progress%1)+1)%1;let mapX=72+48*Math.sin(mapT*Math.PI*2)+7*Math.sin(mapT*Math.PI*6),mapY=60-27*Math.cos(mapT*Math.PI*4)-7*Math.sin(mapT*Math.PI*2);mapdot.setAttribute('cx',mapX);mapdot.setAttribute('cy',mapY);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.querySelector('#toast').classList.remove('show')}}
// AI and player positioning continue to render during intro
racers.forEach((r,i)=>{if(state==='ready'){r.progress=-i*.014;r.speed=0}place(r,dt)});
let player=racers[0],f=frame(((player.progress%1)+1)%1),follow=new THREE.Vector3(-f.tangent.x,0,-f.tangent.z);let desired=player.bike.position.clone().addScaledVector(follow,10).add(new THREE.Vector3(0,5.2,0));camera.position.lerp(desired,1-Math.exp(-dt*3.4));let look=player.bike.position.clone().addScaledVector(f.tangent,8);look.y+=1.2;camera.lookAt(look);if(state==='ready'){camera.position.set(player.bike.position.x-f.tangent.x*10,player.bike.position.y+5.2,player.bike.position.z-f.tangent.z*10);camera.lookAt(look)}
}
let last=performance.now();function animate(now){requestAnimationFrame(animate);let dt=Math.min((now-last)/1000,.04);last=now;update(dt);renderer.render(scene,camera)}requestAnimationFrame(animate);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
</script></body></html>

